<?php if(!isset($lista,$todas,$db)){http_response_code(403);exit;}
function cengi_ins_pago_etiqueta(array $s) {
    if($s['tipo_pago']==='Exonerado')return 'Sin costo';
    if(cengi_ins_estado_cobro($s)==='pagado')return 'Pagado';
    if($s['tipo_pago']==='Propio')return 'Pago por verificar';
    return !empty($s['proforma_id'])?'Pago proforma':'Pendiente de proforma';
}
$stats=['Pago proforma'=>0,'Pendiente de proforma'=>0,'Pagado'=>0];foreach($todas as $s){$label=cengi_ins_pago_etiqueta($s);if(isset($stats[$label]))$stats[$label]++;}
?>
<div class="ins-kpis"><?php foreach($stats as $label=>$n): ?><div class="ins-kpi is-verde"><span class="ins-kpi-body"><span class="ins-kpi-val"><?= $n ?></span><span class="ins-kpi-label"><?= $label ?></span></span></div><?php endforeach; ?></div>
<section class="pp-card"><p>Participantes confirmados. La revisión de interesados se realiza en Interesados y la vinculación de proformas en Validaciones y pagos.</p><form method="get" class="ins-toolbar"><input type="hidden" name="vista" value="inscripciones"><label class="ins-field">Buscar inscrito o curso<input name="q" type="search" value="<?= cengi_pp_h($busqueda) ?>"></label><button class="btn btn-default">Buscar</button></form></section>
<section class="ins-table-card"><div class="pp-table-wrap"><table class="cengi-org-table ins-table"><thead><tr><th>Participante</th><th>Curso</th><th>Quién paga</th><th>Estado de pago</th><th>Validado por / verificado por</th></tr></thead><tbody>
<?php foreach($lista as $s): ?><tr><td data-label="Participante"><strong><?= cengi_pp_h($s['nombre_participante']) ?></strong><span class="pp-sub"><?= cengi_pp_h($s['nombre_ingenios']) ?></span></td><td data-label="Curso"><?= cengi_pp_h($s['plan_nombre']) ?></td><td data-label="Quién paga"><?= cengi_pp_h($s['tipo_pago']) ?></td><td data-label="Estado de pago"><span class="ins-pill is-verde"><?= cengi_ins_pago_etiqueta($s) ?></span><?php if($s['proforma_id']): ?><span class="pp-sub">Proforma #<?= (int)$s['proforma_numero'] ?></span><?php endif; ?><?php if($s['tipo_pago']==='Propio'): ?><span class="ins-boleta"><?= (string)$s['boleta']!=='' ? 'Boleta '.cengi_pp_h($s['boleta']) : 'Sin número de boleta' ?><?= $s['pago_fecha'] ? ' · '.cengi_pp_fecha($s['pago_fecha']) : '' ?><?= $s['monto_comprobante']!==null ? ' · '.cengi_ins_dinero($s['monto_comprobante'],$s['moneda']) : '' ?></span><?php if(!empty($s['comprobante_ruta'])): ?><a class="ins-comprobante" target="_blank" rel="noopener" href="comprobante_inscripcion.php?s=<?= (int)$s['id_solicitud'] ?>"><span class="glyphicon glyphicon-paperclip" aria-hidden="true"></span> Ver comprobante</a><?php else: ?><span class="pp-sub ins-sin-comprobante">Sin comprobante adjunto</span><?php endif; ?><?php endif; ?></td><td data-label="Validado por / verificado por"><?php if($s['tipo_pago']==='Propio'&&!empty($s['pago_validado_por'])): ?><span class="pp-sub">Validado por: <?= cengi_pp_h($s['pago_validado_por']) ?> · <?= cengi_pp_h($s['pago_validado_rol']) ?></span><span class="pp-sub">Evidencia: <?= cengi_pp_h($s['pago_validacion_evidencia']) ?></span>Verificado por: <?php endif; ?><?= cengi_pp_h($s['tipo_pago']==='Ingenio'?$s['validacion_ingenio_por']:$s['pago_verificado_por']) ?><span class="pp-sub"><?= cengi_pp_h($s['tipo_pago']==='Ingenio'?$s['validacion_ingenio_nota']:$s['pago_nota']) ?></span></td></tr><?php endforeach; ?>
<?php if(!$lista): ?><tr><td colspan="5">No hay inscritos confirmados con estos filtros.</td></tr><?php endif; ?></tbody></table></div></section></main></body></html>
